"""Settings consumed by the application.

The shared loader (:mod:`config_loader`) parses the ``key = value`` files under
``config/``; this module exposes the typed accessors the application and its
entry points use.
"""

from __future__ import annotations

from typing import Any, Dict

DEFAULTS: Dict[str, str] = {
    "LOG_LEVEL": "info",
    "HTTP_PORT": "8080",
    "WORKER_CONCURRENCY": "4",
}


class Settings:
    """Read-only view over the loaded configuration values."""

    def __init__(self, values: Dict[str, Any]) -> None:
        self._values = dict(values)

    def get(self, key: str, default=None):
        if key in self._values:
            return self._values[key]
        return DEFAULTS.get(key, default)

    def require(self, key: str) -> str:
        value = self.get(key)
        if value is None:
            raise KeyError(f"missing required setting: {key}")
        return value
